/** A new API key, with its secret. The secret is shown only here. */
export type CreatedApiKeyResponse = ApiKeyResponse & {
  /**
   * The key. Send it as `Authorization: Bearer <key>`; no other header is needed: the key
   * names its tenant. Store it now: it cannot be shown again. Shape: `axk1_`, the tenant ID
   * (32 lowercase hex digits), `_`, then a random part. Keys created in older versions start
   * with `axk_` and keep working.
   */
  key: string;
};

/** A new endpoint and its signing secret, shown only once. */
export type CreatedEndpointResponse = EndpointResponse & {
  /**
   * Verify the `webhook-signature` header of each request with this secret (Standard
   * Webhooks). Store it now: it cannot be shown again, only replaced.
   */
  secret: string;
};

/** A SCIM token just created: the only time its secret is shown. */
export type CreatedScimTokenResponse = ScimTokenResponse & {
  /**
   * Path of the SCIM endpoint on this server; put the server's public address in front of it
   * for the identity provider's "tenant URL" / "base URL".
   */
  scim_base_path: string;
  /**
   * The token itself (`axscim1_…`). Paste it into the identity provider as the secret token /
   * API token; it is not shown again.
   */
  token_secret: string;
};

/** ISO 4217 currency code in upper case, e.g. `USD`, `EUR`, `VND`. Only codes in circulation that have minor units are accepted. */
export type Currency = string;

/** The total of one currency (or of a figure without money: `currency` is null). */
export type CurrencyTotalResponse = {
  /** Sum in minor units of `currency`, as a base-10 integer string. */
  amount: string;
  /** Number of facts. */
  count: number;
  /** ISO 4217 code; null for figures that count things. */
  currency?: string | null;
  /** Sum of the counts. */
  quantity: number;
};

/** The tenant of the caller. */
export type CurrentTenant = {
  id: string;
  /**
   * `production` (a real tenant) or `sandbox` (a test copy: partners are simulated, mail and
   * webhooks do not leave, nothing done here counts in the real tenant).
   */
  kind?: string;
  /** `single` (one tenant) or `multi` (many tenants on one installation). */
  mode: string;
  name: string;
  /** Whether this is the platform tenant (the operator's own). */
  platform: boolean;
  /**
   * Read-only: data can be read but every change is refused with `403 tenant_read_only`.
   * Always present.
   */
  read_only: boolean;
  /** Sandbox only: when it is deleted unless extended. */
  sandbox_expires_at?: string | null;
  /** Sandbox only: the real tenant it was made from. */
  sandbox_of?: string | null;
  slug: string;
  status: string;
};

/** A custom field of the tenant. */
export type CustomFieldView = {
  active: boolean;
  created_at: string;
  /**
   * `text`, `long_text`, `integer`, `decimal`, `boolean`, `date`, `datetime`, `option`,
   * `options`, `url`, `email`, `phone`, `media` or `reference`.
   */
  data_type: string;
  /** Any JSON value of the field's type. */
  default?: unknown;
  /** Lists filter on it (`cf.<key>=`). */
  filterable: boolean;
  /** Help texts by language. */
  help: {
    [key: string]: string;
  };
  id: string;
  /** `snake_case`, never changes: the key in the records' `custom_fields`. */
  key: string;
  /** Labels by language. */
  labels: {
    [key: string]: string;
  };
  /** Longest text, largest number (or date). */
  max?: string | null;
  /** Shortest text, smallest number (or date as `YYYY-MM-DD`). */
  min?: string | null;
  /** Allowed values of `option` / `options`. */
  options: string[];
  /** Personal data: goes into personal-data exports and erasure. */
  personal_data: boolean;
  position: number;
  /** With `reference`: the record type it points to. */
  reference_kind?: string | null;
  required: boolean;
  /** Digits after the decimal point of `decimal` (0 to 6). */
  scale?: number | null;
  /** The record type, e.g. `content.entry`. */
  target: string;
  updated_at: string;
  /** `internal` (staff only), `public` (in public reads) or `buyer_input` (end users fill it). */
  visibility: string;
};

