/** Envelope of a single result. */
export type Data_LedgerBankAccount = {
  /** A bank account money is transferred into (the unit's own account, never the platform's). */
  data: {
    account_name: string;
    account_number: string;
    /** NAPAS bank identification number, e.g. `970436`. */
    bank_bin: string;
    created_at: string;
    /** Bank feed that reports the transfers, if any. */
    feed_provider?: string | null;
    id: string;
    org_id: string;
    /** `active` or `disabled`. */
    status: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerBankFeedReceipt = {
  /** Receipt of a bank feed notification. */
  data: {
    /** Transactions stored now (ones sent before are not counted). */
    stored: number;
  };
};

/** Envelope of a single result. */
export type Data_LedgerBookResponse = {
  /** A book: the ledger of one organization unit (an accounting entity). */
  data: {
    /** Accounting currency of the book. */
    base_currency: string;
    /** Last day of the latest closed period: no entry may be dated on or before it. */
    closed_through?: string | null;
    created_at: string;
    /** First month of the fiscal year, 1 to 12. */
    fiscal_year_start_month: number;
    id: string;
    /** The unit that keeps the book. */
    org_id: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerChainCheck = {
  /** The result of checking a book's hash chain. */
  data: {
    book_id: string;
    broken?: LedgerChainBreak | null;
    /** Number of sealed entries checked (when intact). */
    checked: number;
    checked_at: string;
    /** `true` when every sealed entry and seal is as it was sealed. */
    intact: boolean;
  };
};

/** Envelope of a single result. */
export type Data_LedgerEntry = {
  /** A ledger entry. */
  data: {
    actor_user_id?: string | null;
    book_id: string;
    description: string;
    /** Accounting day, `YYYY-MM-DD`. */
    effective_date: string;
    id: string;
    lines: LedgerEntryLine[];
    /** The unit the book belongs to. */
    org_id: string;
    period_id: string;
    posted_at: string;
    reference: string;
    /** The entry that reverses this one, if any. */
    reversed_by_entry_id?: string | null;
    /** The entry this one reverses. */
    reverses_entry_id?: string | null;
    /** When the entry was sealed into the hash chain; `null` while not yet sealed. */
    sealed_at?: string | null;
    /** Position in the book's hash chain; `null` until the entry is sealed (within seconds). */
    sequence?: number | null;
    source_id?: string | null;
    source_kind: string;
    source_module: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerExceptionResponse = {
  /** A difference waiting for a person. */
  data: {
    created_at: string;
    details: Record<string, unknown>;
    id: string;
    /**
     * `amount_mismatch`, `unmatched_credit`, `duplicate_payment`, `missing_in_statement`,
     * `unknown_in_statement` or `late_payment`.
     */
    kind: string;
    note?: string | null;
    resolution?: string | null;
    resolved_by?: string | null;
    /** `open`, `resolved` or `ignored`. */
    status: string;
    /** The record concerned, e.g. `ledger.payment:<id>`. */
    subject: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerExchangeRate = {
  /** An exchange rate in force from a day: 1 `base` = `rate` `quote`. */
  data: {
    /** ISO 4217 code, e.g. `USD`. */
    base: string;
    created_at: string;
    /** First day the rate is used; it stays in force until a later rate of the same pair. */
    effective_date: string;
    id: string;
    /** ISO 4217 code, e.g. `VND`. */
    quote: string;
    /** Units of `quote` for one unit of `base`, as a decimal string, e.g. `"25345.5"`. */
    rate: DecimalString;
    /** `manual` (entered by a person) or `provider:<name>` (fetched from a rate source). */
    source: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerFlowSettings = {
  /** The money-flow settings in force for a unit (set on it or inherited from the nearest unit above). */
  data: {
    cod_remittance: LedgerCodRemittance;
    /** Days the seller's share is held after the money comes in (return window), 0 to 365. */
    hold_days: number;
    /** The settings come from a unit above. */
    inherited: boolean;
    mode: LedgerFlowMode;
    /** The unit asked about. */
    org_id: string;
    /** Payment partner used in the collect and split modes. */
    payment_provider?: string | null;
    /** Partner that pays the sellers out (collect mode). */
    payout_provider?: string | null;
    /**
     * The unit the settings are set on (its book gets the entries in the collect and split
     * modes); `null` when nothing is set and the defaults apply.
     */
    source_org_id?: string | null;
    updated_at?: string | null;
  };
};

/** Envelope of a single result. */
export type Data_LedgerHold = {
  /** The seller's share of a sale held until the return window ends. */
  data: {
    /** Still held: the sale minus fees, withholding and refunds so far. */
    amount: Money;
    book_id: string;
    created_at: string;
    id: string;
    /** The unit of the book (the marketplace). */
    org_id: string;
    /** Held when the money came in. */
    original: Money;
    /** When the job moves the money to the seller's available balance. */
    release_at: string;
    /** The entry that moved the money to the available balance. */
    release_entry_id?: string | null;
    seller_org_id: string;
    source_id: string;
    source_module: string;
    /** `held` or `released`. */
    status: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerPayment = {
  /** A payment collected through a licensed partner. */
  data: {
    amount: Money;
    /** Bank transfer payments: the receiving bank account (of the unit, never of the platform). */
    bank_account_id?: string | null;
    book_id: string;
    captured_at?: string | null;
    /** Partner page where the buyer pays. */
    checkout_url?: string | null;
    created_at: string;
    description: string;
    expires_at: string;
    id: string;
    /** `card`, `wallet`, `vietqr`… */
    method: string;
    /** The unit that receives the money (its book gets the entries). */
    org_id: string;
    /** Partner, e.g. `vnpay`. */
    provider: string;
    /** Id of the transaction at the partner, once created there. */
    provider_ref?: string | null;
    /** QR payload, when the partner gives one, or the VietQR code of a bank transfer payment. */
    qr_payload?: string | null;
    reference: string;
    /** Refunded or being refunded. */
    refunded: Money;
    source_id?: string | null;
    /** Module that asked for the payment (`plans`, `orders`…) and its document. */
    source_module: string;
    /**
     * `pending`, `succeeded`, `failed`, `expired` or `needs_review` (the partner reported another
     * amount; see the exceptions).
     */
    status: string;
    /** Bank transfer payments: the code the buyer must keep in the transfer description. */
    transfer_code?: string | null;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerPaymentDetail = {
  /** A payment with its refunds. */
  data: LedgerPayment & {
    refunds: LedgerRefund[];
  };
};

/** Envelope of a single result. */
export type Data_LedgerPayout = {
  /** A payout of a seller's available balance through the payout partner. */
  data: {
    amount: Money;
    book_id: string;
    created_at: string;
    description: string;
    failure_reason?: string | null;
    id: string;
    /** The unit of the book (the marketplace). */
    org_id: string;
    /** The seller paid. */
    payee_org_id: string;
    provider: string;
    provider_ref?: string | null;
    reference: string;
    /**
     * `pending` (the partner has not answered yet; send the same request again), `sent` (the
     * partner is working on it), `succeeded` or `failed` (the money is back on the seller's
     * available balance).
     */
    status: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerPeriodResponse = {
  /** An accounting period (a calendar month). */
  data: {
    book_id: string;
    closed_at?: string | null;
    closed_by?: string | null;
    ends_on: string;
    /** Number of entries dated in the period. */
    entries: number;
    id: string;
    /**
     * How many of them are already sealed into the book's hash chain (sealing runs in the
     * background shortly after posting).
     */
    sealed_entries: number;
    starts_on: string;
    /** `open` or `closed`. */
    status: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerReconciliationResponse = {
  /** A reconciliation run. */
  data: {
    created_at: string;
    created_by?: string | null;
    /** The day reconciled. */
    date: string;
    /** Differences sent to the exceptions. */
    exceptions: number;
    id: string;
    /** Statement lines read. */
    lines: number;
    /** Lines that matched the book. */
    matched: number;
    provider: string;
    /** `completed` or `failed`. */
    status: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerRefund = {
  /** A refund of (part of) a payment. */
  data: {
    amount: Money;
    created_at: string;
    id: string;
    payment_id: string;
    provider_ref?: string | null;
    reason: string;
    reference: string;
    /** `pending`, `succeeded` or `failed`. */
    status: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerSealStatus = {
  /** How many entries of a book are in its hash chain. */
  data: {
    book_id: string;
    /** When the oldest entry not yet sealed was posted; entries are sealed within seconds. */
    oldest_unsealed_at?: string | null;
    /** The period counted, or `null` for the whole book. */
    period_id?: string | null;
    sealed: number;
    total: number;
  };
};

/** Envelope of a single result. */
export type Data_LedgerTrialBalanceResponse = {
  /** A trial balance. */
  data: {
    accounts: LedgerTrialBalanceRow[];
    book_id: string;
    from: string;
    org_id: string;
    to: string;
    totals: LedgerTrialBalanceTotal[];
  };
};

/** Envelope of a single result. */
export type Data_LedgerVietqrPreview = {
  /** A sample VietQR code for a bank account. */
  data: {
    amount: Money;
    /** The account the code pays into. */
    bank_account: LedgerBankAccount;
    /** The transfer note inside the code. */
    memo: string;
    /** The VietQR (EMVCo) text to draw as a QR code. */
    qr_payload: string;
  };
};

/** Envelope of a single result. */
export type Data_LedgerWebhookReceipt = {
  /** Receipt of a partner notification. */
  data: {
    received: boolean;
  };
};

/** Envelope of a single result. */
export type Data_LibrarySummaryResponse = {
  /** Totals of the media library. */
  data: {
    /**
     * Total size in bytes of the items not in the trash (their current content, without the
     * smaller copies of images).
     */
    bytes: number;
    /**
     * Images not in the trash with no text alternative and not marked `decorative`: the items
     * `GET /api/v1/media?alt_missing=true` lists.
     */
    images_missing_alt: number;
    /** Items not in the trash. */
    items: number;
    /** Items in the trash. */
    trashed_items: number;
  };
};

/** Envelope of a single result. */
export type Data_ListResponse = {
  /** A newsletter list, as admins see it. */
  data: {
    created_at: string;
    description: NewsletterText;
    /** Public sign-ups get a confirmation mail and receive nothing until they open its link. */
    double_opt_in: boolean;
    id: string;
    /** Unique; websites send it to subscribe. */
    key: string;
    name: NewsletterText;
    new_post_locale?: NewsletterLocale | null;
    /** What happens when the `content` module publishes a post. */
    new_posts: NewPosts;
    /** Shown by `GET /api/v1/newsletter/public/lists` and open to public sign-up. */
    public: boolean;
    /** Subscriptions by status. */
    subscriptions: SubscriptionCounts;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_LoginLinkResponse = {
  /** What to keep while waiting for the mail. */
  data: {
    /**
     * With `bind_device`: send it back with the token. `null` otherwise. Returned even when no
     * account has this email, so the answer reveals nothing.
     */
    device_secret?: string | null;
  };
};

/** Envelope of a single result. */
export type Data_LoyaltyRule = {
  /** A loyalty rule: how points are earned and redeemed from `effective_from` on. */
  data: {
    /** Paid for goods per earning unit (smallest currency unit), e.g. `10000`. */
    earn_per_minor: number;
    effective_from: string;
    id: string;
    /** Points pay at most this share of an order, in basis points (`5000` = 50%). */
    max_redeem_ratio_bp: number;
    min_redeem_points: number;
    /** What one point is worth when redeemed. */
    point_value: Money;
    /** Points per earning unit. */
    points_per_unit: number;
    points_valid_months: number;
  };
};

/** Envelope of a single result. */
export type Data_MeResponse = {
  /** The signed-in user and what they may do. */
  data: {
    /**
     * How you are in that tenant: `direct` (your own tenant), `delegation` (a parent tenant's
     * delegation, `GET /api/v1/auth/me/tenants`) or `support` (platform staff with a support
     * grant).
     */
    access: string;
    /**
     * `true` when a role grants every permission (the `admin` role); `permissions`
     * is then empty.
     */
    all_permissions: boolean;
    created_at: string;
    /** Normalized email: lower case, no surrounding spaces. */
    email: string;
    /**
     * When the email was confirmed through a verification mail; `null` while it is
     * not verified (ask for a new mail with `POST /api/v1/auth/me/email/verification`).
     */
    email_verified_at?: string | null;
    /**
     * Whether the account has a password. Without one (signed in with a passkey), set a first
     * password through `POST /api/v1/auth/password-reset`.
     */
    has_password: boolean;
    /**
     * With `delegation` or `support`: the tenant your account belongs to (the profile fields
     * above are of that account); `null` when `direct`.
     */
    home_tenant_id?: string | null;
    id: string;
    /**
     * Preferred language (`en` or `vi`) for mails sent later; `null`: the language of each
     * request. Change it with `PATCH /api/v1/auth/me`.
     */
    locale?: string | null;
    /**
     * `true` when a role of yours needs two-step sign-in and it is off: that role's permissions
     * are left out of `permissions` until you turn on an authenticator app
     * (`POST /api/v1/auth/me/mfa/totp`) or add a passkey.
     */
    mfa_required: boolean;
    /** Display name. */
    name: string;
    pending_email?: PendingEmail | null;
    /** Permissions granted by the user's roles, sorted by name. */
    permissions: string[];
    /** The tenant of this request. `permissions` and `all_permissions` are what you may do here. */
    tenant_id: string;
    /** Preferred IANA time zone; `null`: not set. */
    time_zone?: string | null;
  };
};

/** Envelope of a single result. */
export type Data_MediaItemResponse = {
  /** A media item. Its content is at `url`. */
  data: {
    /**
     * Text alternative for screen readers (the `alt` of an `<img>`); empty when unset. This is
     * the default language's text, used for any language without a translation in `alts`.
     */
    alt: string;
    /**
     * The default `alt` was written from an AI suggestion: label it where it is shown (Vietnam's
     * Law on Artificial Intelligence 134/2025/QH15).
     */
    alt_ai_assisted: boolean;
    /**
     * Translations of `alt` by language (BCP 47 code → text), set with
     * `PUT /api/v1/media/{id}/alts/{locale}`. Show `alts[locale]` when present, else `alt`.
     */
    alts: {
      [key: string]: string;
    };
    /** Caption; empty when unset. */
    caption: string;
    /** Real media type of the content (checked against its first bytes at upload). */
    content_type: string;
    created_at: string;
    /**
     * `true` for a purely decorative image: its empty `alt` is on purpose (render `alt=""`), so
     * it does not count as missing one.
     */
    decorative: boolean;
    /** The folder holding the item; `null` for the root. */
    folder_id?: string | null;
    /** Height in pixels; only for raster images. */
    height?: number | null;
    id: string;
    /** File name, given back on download. */
    name: string;
    /** SHA-256 of the content, as 64 hex digits. */
    sha256: string;
    /** Size in bytes. */
    size: number;
    /** Tags of the item, sorted by name. */
    tags: string[];
    /** Title; empty when unset. */
    title: string;
    /** When the item was moved to the trash; `null` when it is not in the trash. */
    trashed_at?: string | null;
    updated_at: string;
    /** The user who uploaded the item; `null` once that account is deleted. */
    uploaded_by?: string | null;
    /**
     * Display name of `uploaded_by`, with `include=uploader` on the list: `null` when the
     * account no longer exists; absent otherwise.
     */
    uploaded_by_name?: string | null;
    /**
     * Where to load the content, with its version: the address changes when the content
     * does, so it may be cached for a long time. Public items load without signing in.
     */
    url: string;
    /**
     * Smaller copies of a JPEG, PNG, GIF or WebP image, narrowest first, for `srcset`.
     * Made in the background shortly after an upload or a content change: empty until then,
     * and for other types.
     */
    variants: VariantResponse[];
    /** Version of the content; changes when the content is replaced. */
    version_id: string;
    visibility: Visibility;
    /** Width in pixels; only for raster images (JPEG, PNG, GIF, WebP, AVIF). */
    width?: number | null;
  };
};

/** Envelope of a single result. */
export type Data_MembershipTier = {
  /** A membership tier version. */
  data: {
    code: string;
    /** Earning multiplier in basis points (`12000` = ×1.2). */
    earn_multiplier_bp: number;
    effective_from: string;
    id: string;
    name: string;
    /** Higher wins when several tiers are reached. */
    rank: number;
    /** Spent on goods over the last 12 months to reach the tier. */
    threshold: Money;
  };
};

/** Envelope of a single result. */
export type Data_MenuResponse = {
  /** A navigation menu. */
  data: {
    created_at: string;
    id: string;
    items: MenuItemResponse[];
    key: string;
    locale: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_MfaChallengeResponse = {
  /** Two-step sign-in: the password was right, a code is needed. */
  data: {
    /** Seconds left to send the code. */
    expires_in: number;
    /**
     * Accepted kinds of code: `totp` (6 digits from the authenticator app) and
     * `recovery_code`.
     */
    methods: string[];
    /** Send this with the code to `POST /api/v1/auth/login/mfa`. Works once. */
    mfa_token: string;
  };
};

/** Envelope of a single result. */
export type Data_MfaStatusResponse = {
  /** Your two-step sign-in settings. */
  data: {
    /** Unused recovery codes left. Make new ones before they run out. */
    recovery_codes_remaining: number;
    /** Sign-in asks for a code from an authenticator app. */
    totp_enabled: boolean;
  };
};

/** Envelope of a single result. */
export type Data_MigrationDryRun = {
  /** The pending migrations a dry run found. */
  data: {
    /** Always `true`. */
    dry_run: boolean;
    /** Per placement, the migrations that would run (empty: up to date). */
    pending: PlacementMigrationList[];
  };
};

/** Envelope of a single result. */
export type Data_MigrationRun = {
  /** A run of the migrations of the tenant databases (placements). */
  data: {
    /** Migrations applied, per placement done (also when a later placement failed). */
    applied: PlacementMigrationList[];
    created_at: string;
    /**
     * Why it failed: the placement and its error. Fix it and start a new run; what is already
     * applied is skipped.
     */
    error?: string | null;
    id: string;
    /** The placement it runs on; `null`: every placement, by name. */
    placement?: string | null;
    requested_by?: string | null;
    /** `pending`, `running`, `done` or `failed`. */
    status: string;
    updated_at: string;
  };
};

/** Envelope of a single result. */
export type Data_ModuleInfo = {
  /** A module installed in this server, and everything it declares. */
  data: {
    /**
     * `true` when no plan can turn the module off (sign-in, files, audit…). Otherwise a tenant
     * whose plan does not include the module gets `403 module_not_enabled` from its endpoints.
     */
    always_enabled: boolean;
    /** Endpoints of the module that are deprecated. */
    deprecations: ModuleDeprecation[];
    /** One sentence about what the module does; empty when the module gives none. */
    description: string;
    /** Events the module emits. */
    events: ModuleEvent[];
    /** Features of the module that a plan turns on or off (`<module>.<name>`). */
    features: ModuleFeature[];
    /** `true` for the modules the server always installs (`kernel`, `antispam`). */
    internal: boolean;
    /** Kinds of background job the module runs. */
    jobs: string[];
    /** Languages, besides English, the module's error messages are translated to. */
    languages: string[];
    /** Limits of the module that a plan sets (`<module>.<name>`). */
    limits: ModuleLimit[];
    /** Database migrations of the module, in the order they apply. */
    migrations: ModuleMigration[];
    /**
     * The module name. Its REST endpoints live under `/api/v1/<name>`; its tables,
     * permissions, events, error codes and job kinds start with `<name>`.
     */
    name: string;
    /** Permissions the module declares; roles grant them. */
    permissions: ModulePermission[];
    /** Place in the start order, from 0. A module starts after the modules it depends on. */
    position: number;
    /** MCP prompts (templates for common jobs) the module offers at `/mcp`. */
    prompts: ModulePrompt[];
    /** Modules this module uses; a plan that turns this module on must turn them on too. */
    requires: string[];
    /** MCP resources (read-only documents) the module offers at `/mcp`. */
    resources: ModuleResource[];
    /** Recurring jobs the module schedules. */
    schedules: ModuleSchedule[];
    /**
     * `official`, or `experimental`: the module's API and data may still change between
     * releases, and it only runs where the installation turns it on (`AUTOXIDE_MODULES`).
     */
    stability: string;
    /** Events the module listens to; `*` means every event. */
    subscriptions: string[];
    /** MCP tools the module offers at `/mcp`. */
    tools: ModuleTool[];
  };
};

