    attempts: number;
    category: string;
    channel: string;
    created_at: string;
    dedupe_key: string;
    /** Why it failed (error code of the provider, `unsubscribe_url_missing`, `zns_template_missing`…). */
    error_code?: string | null;
    id: string;
