    /**
     * Until when it waits for the mail link (`pending_email`) or the identity checks
     * (`awaiting_kyc`).
     */
    expires_at: string;
    id: string;
    kyc?: SignupKyc | null;
    /** Language of the mails: `en` or `vi`. */
